export function Partners({ compact = false }: { compact?: boolean }) {
  const partners = [
    { name: "Ora", href: "https://ora.ai", Logo: OraLogo },
    { name: "Vercel", href: "https://vercel.com", Logo: VercelLogo },
    { name: "Mintlify", href: "https://www.mintlify.com", Logo: MintlifyLogo },
    { name: "Auth0", href: "https://auth0.com", Logo: Auth0Logo, hidden: true },
    { name: "Stripe", href: "https://stripe.com", Logo: StripeLogo, hidden: true },
  ] as const;
  return (
    <div
      className={compact ? "" : "mt-6 mb-10"}
      id={compact ? undefined : "collaborators"}
    >
      <p
        className={`font-mono tracking-widest ${
          compact
            ? "text-[0.625rem] text-muted-foreground/50 mb-3"
            : "text-[0.6875rem] text-muted-foreground/50 mb-4"
        }`}
      >
        in collaboration with
      </p>
      <ul
        className={`flex flex-nowrap items-center overflow-x-auto py-0.5 ${
          compact ? "gap-x-6" : "gap-x-6 sm:gap-x-8"
        }`}
      >
        {partners
          .filter((p) => !("hidden" in p && p.hidden))
          .map(({ name, href, Logo }) => (
          <li key={name} className="shrink-0">
            <a
              href={href}
              target="_blank"
              rel="noreferrer"
              aria-label={name}
              className={`inline-flex items-center text-foreground/90 hover:text-foreground transition-colors ${
                compact ? "h-5 text-[20px]" : "h-6 sm:h-7 text-[24px] sm:text-[28px]"
              }`}
            >
              <Logo />
            </a>
          </li>
        ))}
      </ul>
    </div>
  );
}

function OraLogo() {
  return (
    <span className="font-mono font-bold tracking-wide leading-none text-[1.45em]">
      ora
    </span>
  );
}

